  "proposed_components": [
    {
      "class_code": 22,
      "payload": {
        "name": "pc-transfer-06",
        "description": "Classify a raw offset field into missing, null, integer(2..11) or invalid. Pure logic; no Tool call, no I/O, no host calls. Returns only the declared kind and offset fields.",
        "content": "def classify_offset(raw):\n    if 'offset' not in inputs:\n        result = {'kind': 'missing', 'offset': None}\n    else:\n        offset = inputs['offset']\n        if offset is None:\n            result = {'kind': 'null', 'offset': None}\n        elif type(offset) is int and not type(offset) is bool and 2 <= offset <= 11:\n            result = {'kind': 'integer', 'offset': offset}\n        else:\n            result = {'kind': 'invalid', 'offset': None}\n    return result\nresult = classify_offset(inputs.get('offset'))"
      }
    }
  ]
}
